class LmdbDeferredSemiAntiFeedbackTest {

	@Test
	void earlySemiAntiObservationIsRetained(@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		run(path, false, false);
	}

	@Test
	void readySemiAntiObservationStillLearns(@TempDir(cleanup = CleanupMode.NEVER) Path path) throws Exception {
		run(path, true, false);
	}

	@Test
	void earlySemiAntiObservationCannotTrainAfterCommit(@TempDir(cleanup = CleanupMode.NEVER) Path path)
			throws Exception {
		run(path, false, true);
	}

	private static void run(Path path, boolean ready, boolean commit) throws Exception {
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		LmdbStore store = new HeldStore(path, entered, release);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			assertTrue(entered.await(10, TimeUnit.SECONDS), "optional provider publication is held");
			if (ready) {
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			}
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			statistics.bindExecutionSnapshot(OptionalLong.of(statistics.estimatorRuntime().snapshotVersion()));
			if (!ready) {
				assertNull(statistics.estimatorRuntime().feedback(), "the observation precedes publication");
			}
			statistics.recordSemiAntiOutcome(filter(), observation());
			if (commit) {
				try (var connection = repository.getConnection()) {
					var values = connection.getValueFactory();
					connection.add(values.createIRI("urn:semi-anti:new"), values.createIRI("urn:semi-anti:predicate"),
							values.createIRI("urn:semi-anti:value"));
				}
			}
			if (!ready) {
				release.countDown();
				LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			}
			LmdbEvaluationStatistics current = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			LmdbOperatorFeedbackStats.SemiAntiEstimate estimate = current.estimatorRuntime()
					.semiAntiFeedback(filter(), "NOT_EXISTS", "memoized-correlated");
			if (commit) {
				assertNull(estimate, "an observation from before a commit cannot teach the new snapshot");
			} else {
				assertNotNull(estimate, "a completed current-snapshot semi/anti observation reaches its provider");
				assertEquals(1L, estimate.observationCount(), "the observation is applied once");
				assertEquals(18L, estimate.rhsRowsExamined());
				assertEquals(10L, estimate.cacheLookups());
			}
		} finally {
			release.countDown();
			repository.shutDown();
		}
	}

	private static Filter filter() {
		TupleExpr query = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:semi-anti:p> ?o . FILTER NOT EXISTS { ?s <urn:semi-anti:q> ?v } }", null)
				.getTupleExpr();
		PlanningGraphDomains.capture(query, PlanningGraphDomain.defaultGraph());
		Filter[] result = new Filter[1];
		query.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				if (result[0] == null) {
					result[0] = filter;
				}
				super.meet(filter);
			}
		});
		return result[0];
	}

	private static EvaluationStatistics.SemiAntiOutcomeObservation observation() {
		return new EvaluationStatistics.SemiAntiOutcomeObservation("NOT_EXISTS", "memoized-correlated",
				"memoized-correlated", 10L, 6L, 4L, 4L, 2L, 2L, 6L, 18L, 4L, 4L, 0L, 0L, 10L, true, "", "");
	}

	private static final class HeldStore extends LmdbStore {
		private final CountDownLatch entered;
		private final CountDownLatch release;

		HeldStore(Path path, CountDownLatch entered, CountDownLatch release) {
			super(path.toFile(), config());
			this.entered = entered;
			this.release = release;
		}

		private static LmdbStoreConfig config() {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
			config.setExperimentalQueryOptimizations(true);
			return config;
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, sketches, null,
					(tripleDir, props, settings, values) -> new TripleStore(tripleDir, props, settings, values) {
						@Override
						void startBackgroundIndexRebuild() {
							entered.countDown();
							try {
								release.await();
							} catch (InterruptedException failure) {
								Thread.currentThread().interrupt();
								return;
							}
							super.startBackgroundIndexRebuild();
						}
					});
		}
	}
}
